export type CoachInput = {
  text: string;
  version: string;
  game?: string;
  change?: ChangeContext | null;
  /** The plan screen's lanes (lib/cyrus/planner/decide.ts), for capability lines and the change-lane check. */
  lanes?: Pick<PlannedLane, "lane" | "state" | "label" | "warning" | "capability">[] | null;
  /** Lanes the plan screen kept out of a change because its text does not ask for them (./plan-hook.ts). */
  held?: Lane[] | null;
  /** The technique switch (CYRUS_MC_TECHNIQUES: vein miners, mob catchers). false = say they are not available yet; undefined = unknown (the matrix limits apply). */
  techniques?: boolean;
};

// ---------- word rules (what a prompt already says) ----------
const VERSION_RE = /\b(1\.\d{1,2}(?:\.\d{1,2})?|26\.\d(?:\.\d{1,2})?)\b/g;
const NUM_WORDS = /\b(one|two|three|four|five|six|seven|eight|nine|ten|twelve|fifteen|twenty|thirty|fifty|hundred|double|twice|half|triple)\b/gi;
export function analyzePrompt(input: CoachInput): CoachReport {
  const text = String(input.text ?? "").replace(/\r/g, "").trim().slice(0, 4000);
  const game = input.game ?? "minecraft";
  const change = input.change ?? null;
  const w = words(text);
  const kinds = Object.fromEntries(Object.entries(KIND).map(([k, re]) => [k, re.test(text)])) as Ctx["kinds"];
  const match = matchArchetype(text) ?? (change ? matchArchetype(`${change.name} ${change.summary ?? ""}`) : null);
  const tpl = match ? TEMPLATE_BY_ID[match.id] ?? null : null;
  const facts = archetypeFacts(tpl?.id, input.version);
  const name = guessName(text) ?? change?.name ?? null;
  const ctx: Ctx = { tpl, text, kinds, version: input.version, name, change };

  // Which details matter for THIS request.
  const rel = new Set<GapId>(change ? ["what", "scope", "edgeCases"] : ["what", "trigger", "numbers", "edgeCases", "config"]);
  if (!change) for (const d of tpl?.dims ?? []) rel.add(d);
  if (change && /\b(radius|range|more|less|fewer|bigger|smaller|faster|slower|increase|decrease|raise|lower|double|half|longer|shorter|max(?:imum)?|limit)\b/i.test(text)) { rel.add("numbers"); rel.add("limits")
  if (kinds.heavy) { rel.add("performance"); rel.add("limits"); rel.add("numbers"); }
  if (kinds.heavy && kinds.world) rel.add("dimensions");
  if (kinds.stateful && !change) rel.add("persistence");
  if (kinds.creates && (kinds.heavy || kinds.mob || /\b(rewards?|loot|gives?|sells?)\b/i.test(text))) rel.add("antiAbuse");
  if (kinds.heavy || kinds.global) rel.add("modes");
  if (kinds.heavy && !change) rel.add("commands");

  // How well the text already covers each one.
  const nums = countNumbers(text);
  const keepPhrase = RISKS.filter((r) => r.clause).some((r) => r.re.test(text));
  const versions = [...text.matchAll(VERSION_RE)].map((m) => m[1]);
  const otherVersion = versions.find((v) => v !== input.version && !input.version.startsWith(`${v}.`)) ?? null;
  const covered = (id: GapId): number => {
    if (id === "what") return w >= 12 ? 1 : w >= 6 ? 0.5 : 0;
    if (id === "numbers") return nums >= 2 ? 1 : nums === 1 ? 0.5 : 0;
    if (id === "version") return otherVersion ? 0 : versions.includes(input.version) ? 1 : 0.5;
    if (id === "scope" && keepPhrase) return 0.5; // "keep everything as is" is what the guard misread: ask what exactly stays
    return SAYS[id].test(text) ? 1 : 0;
  };
  let total = 0, got = 0;
  const gaps: CoachGap[] = [];
  const strengths: string[] = [];
  for (const id of GAP_IDS) {
    if (!rel.has(id)) continue;
    const c = covered(id);
    total += WEIGHT[id];
    got += WEIGHT[id] * c;
    if (c >= 1) strengths.push(id === "numbers" ? `${STRENGTH.numbers} (${nums})` : STRENGTH[id]);
    else gaps.push({ ...question(id, ctx), weight: WEIGHT[id], ...(c > 0 ? { partial: true } : {}) });
  }
  gaps.sort((a, b) => b.weight - a.weight || GAP_IDS.indexOf(a.id) - GAP_IDS.indexOf(b.id));

  const risks = guardRisks(text);
  let score = total ? Math.round((100 * got) / total) : 0;
  if (w < 6) score = Math.min(score, 25);
  else if (w < 12) score = Math.min(score, 45);
  else if (w < 25) score = Math.min(score, 70);
  if (w >= 60 && gaps.length <= 2) score += 5;
  score -= Math.min(30, risks.length * 12);
  if (otherVersion) score -= 5;
  score = Math.max(0, Math.min(100, score));
  const level: CoachLevel = score >= 75 ? "great" : score >= 45 ? "good" : "vague";

  // Honest capability lines (deduplicated, shown before spend).
  const capability: string[] = [];
  const push = (s: string | null | undefined) => { if (s && !capability.includes(s)) capability.push(s); };
  if (otherVersion) push(`Your text mentions Minecraft ${otherVersion}, but this mod is built for ${input.version}. Change the version in the version picker; the text does not change it.`);
  if (PLATFORM.test(text)) push("Cyrus builds Paper server plugins (with a resource pack the server sends to players). Forge, Fabric and other client mods, shaders and client-side features are not built; player
  if (NETWORK.test(text)) push("Cyrus mods cannot use networking (Discord, websites, databases, downloads): that capability is not switched on yet. Cyrus can build the in-game part.");
  const techniqueOff = !!facts && TECHNIQUE_ARCHETYPES.includes(facts.id) && input.techniques === false;
  if (techniqueOff) push(`Not available yet: ${facts!.label.toLowerCase()} are not switched on in Cyrus yet. Cyrus builds the rest of your request and, where it can, a plain version of this one; add this again 
  if (facts && facts.status !== "covered") for (const l of facts.limits) {
    // the switch is on: the matrix line "Off until the owner switches ..." no longer applies
    if (input.techniques === true && TECHNIQUE_ARCHETYPES.includes(facts.id) && /^Off until/.test(l)) continue;
    push(l);
  }
  if (facts) for (const l of facts.versionLines) push(l);
  for (const l of input.lanes ?? []) if ((l.state === "blocked" || (l.state === "build" && l.capability?.availability === "limited")) && l.warning) push(l.warning);

  // Change requests: what is kept, and planned lanes the change text does not ask for.
  const unasked = change && input.lanes ? unaskedChangeLanes(text, input.lanes, game) : [];
  const changeOut = change ? { target: change.name, kept: keptFromBase(change), unasked: unasked.map((lane) => ({ lane, label: LANE_META[lane].label })), held: (input.held ?? []).map((lane) => ({ lane, label: L

  const n = level === "great" ? Math.min(3, gaps.length) : Math.min(6, Math.max(3, gaps.length));
  return {
    v: COACH_REPORT_VERSION, score, level, kind: change ? "change" : "new", version: input.version,

