function validate(ws, rec) {
  const problems = [];
  const fixes = []; // mechanical fixes made here (reported to the model only if a repair follows)
  const res = path.join(ws, "src/main/resources");
  const ymlPath = path.join(res, "plugin.yml");
  if (fs.existsSync(path.join(res, "paper-plugin.yml"))) problems.push("Use plugin.yml, not paper-plugin.yml: delete src/main/resources/paper-plugin.yml.");
  if (!fs.existsSync(ymlPath)) return { problems: ["src/main/resources/plugin.yml is missing."], yml: null };
  let yml;
  try { yml = YAML.parse(fs.readFileSync(ymlPath, "utf8")); } catch (e) { return { problems: [`plugin.yml is not valid YAML: ${e.message}`], yml: null }; }
  if (!yml || typeof yml !== "object") return { problems: ["plugin.yml is empty."], yml: null };
  if (rec.imported) {
    // Cyrus import: the owner's own plugin. Their name rules are Paper's (no spaces here), no runtime library downloads.
    if (!/^[A-Za-z0-9_.-]{1,64}$/.test(String(yml.name || ""))) problems.push("plugin.yml name must be 1-64 letters, digits, '_', '-' or '.'.");
  } else if (!/^[A-Za-z0-9_]{1,40}$/.test(String(yml.name || ""))) problems.push("plugin.yml name must be 1-40 letters, digits or underscores.");
  // For EVERY build (generated and imported): a libraries: section makes Paper download jars from the internet at server start, outside
  // the offline build, the scan and the dependency allowlist. Never allowed.
  { const lp = librariesProblem(yml); if (lp) problems.push(lp); }
  if (!yml.version) problems.push("plugin.yml needs a version.");
  const main = String(yml.main || "");
  if (!/^[a-zA-Z_][\w]*(\.[a-zA-Z_][\w]*)+$/.test(main)) problems.push("plugin.yml main must be a fully-qualified class name.");
  else if (!fs.existsSync(path.join(ws, "src/main/java", main.replace(/\./g, "/") + ".java"))) problems.push(`plugin.yml main is ${main} but src/main/java/${main.replace(/\./g, "/")}.java does not exist.`);
  if (/^(org\.bukkit|io\.papermc|net\.minecraft|com\.destroystokyo|net\.kyori)\./.test(main)) problems.push("The main class must be in your own package.");
  // Pin api-version to the exact Paper version the jar was compiled against.
  // With '1.21' a 1.21.11 build also "loads" on a 1.21.1 server and then crashes
  // on API that version does not have (the Growth incident: Attribute.SCALE ->
  // InvalidPluginException initializing the main class). With '1.21.11' Paper
  // 1.21.1 refuses it cleanly ("Unsupported API version 1.21.11") while 1.21.11+
  // load it. Verified on real Paper 1.21.1 / 1.21.8 / 1.21.11 servers 2026-10-07.
  const apiVersion = rec.mcVersion;
  if (String(yml["api-version"] || "") !== apiVersion) {
    // Mechanical fix, not worth a model round-trip.
    yml["api-version"] = apiVersion;
    // Imported plugin.yml: change that one line only (keeps the owner's comments and layout).
    fs.writeFileSync(ymlPath, rec.imported ? IMP.setApiVersionLine(fs.readFileSync(ymlPath, "utf8"), apiVersion) : YAML.stringify(yml));
  }
  // getCommand("x") without a plugin.yml entry returns null at runtime -> NPE on enable.
  const declared = new Set(Object.keys((yml.commands && typeof yml.commands === "object") ? yml.commands : {}).map((s) => s.toLowerCase()));
  const java = listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java"));
  if (!java.length) problems.push("No Java source files were written.");
  for (const f of java) {
    const text = fs.readFileSync(f.abs, "utf8");
    for (const m of text.matchAll(/getCommand\(\s*"([^"]+)"\s*\)/g)) {
      if (!declared.has(m[1].toLowerCase())) problems.push(`${f.rel} calls getCommand("${m[1]}") but plugin.yml has no command "${m[1]}" (it would crash on enable).`);
    }
    if (!rec.imported && /^\s*public\s+final\s+class\s+\w+\s+extends\s+JavaPlugin/m.test(text)) {

