private static boolean lowNoted;
private static String commandLabel;
/** > 0 while this plugin's own code runs (a wrapped listener, an NxPerf timer or queue): spawns then count as ours. */
private static int ownDepth;
private static int ownSpawnsSecond, deniedSpawnsSecond, deniedSeconds;
private static long deniedSpawnsTotal;

// ------------------------------------------------------------------ lifecycle ----

/** Called first thing in onEnable (inserted by the build service). Safe to call again after a reload. */
public static void init(Plugin p) {
  plugin = p;
  BUDGETS.clear(); RATES.clear(); DEPTH.clear(); TIMED.clear(); PAUSED_LISTENERS.clear(); TIMERS.clear(); QUEUES.clear();
  ON_PAUSE.clear(); ON_RESUME.clear();
  paused = false; pauseReason = null; pauseDetail = null; warnedSettings = ""; WARNED_RADIUS.clear(); ownNanosTick = 0; ownNanosSecond = 0; secondStart = 0; ticksSecond = 0;
  secondsSinceStatus = 0; seconds = 0; lowNoted = false; commandLabel = null; JUDGE.reset();
  ownDepth = 0; ownSpawnsSecond = 0; deniedSpawnsSecond = 0; deniedSeconds = 0; deniedSpawnsTotal = 0;
  enabledAtMs = System.currentTimeMillis();
  readSettings();
  p.getServer().getPluginManager().registerEvents(new SpawnGuard(), p);
  Bukkit.getScheduler().runTaskTimer(p, NxPerf::tick, 1L, 1L);
  Bukkit.getScheduler().runTaskLater(p, () -> { wrapListeners(); hookCommand(); }, 1L);
  p.getLogger().info("[NxPerf] watchdog " + NxPerfCore.VERSION + " on: pauses heavy features below " + NxPerfCore.fmt(S.tpsFloor)
      + " TPS for " + S.windowSeconds + " s (perf.auto-disable=" + S.autoDisable + ")");
}

private static void readSettings() {
  try {
    FileConfiguration c = plugin.getConfig();
    S.autoDisable = c.getBoolean("perf.auto-disable", true);
    S.tpsFloor = c.getDouble("perf.tps-floor", 15.0);
    S.windowSeconds = c.getInt("perf.window-seconds", 10);
    S.maxWorkPerTick = c.getInt("perf.max-work-per-tick", 64);
    S.maxMsPerTick = c.getDouble("perf.max-ms-per-tick", 25.0);
    S.share = c.getDouble("perf.share", 0.25);
    S.maxEntitiesPerSecond = c.getInt("perf.max-entities-per-second", 5);
    S.maxEntitiesPerChunk = c.getInt("perf.max-entities-per-chunk", 20);
    S.maxQueue = c.getInt("perf.max-queue", 2000);
    S.maxRadius = c.getInt("perf.max-radius", 0);
    S.statusLogSeconds = c.getInt("perf.status-log-seconds", 300);
    S.maxSpawnsPerSecond = c.getInt("perf.max-spawns-per-second", 50);
    S.freezeMs = c.getDouble("perf.freeze-ms", 2000.0);
  } catch (RuntimeException e) {
    // keep the defaults: a broken config never switches the watchdog off
  }
  S.clampAll();
  for (NxPerfCore.Budget b : BUDGETS.values()) b.setPerTick(S.maxWorkPerTick);
  // values above the recommended maxima are applied; say so once (and again only when they change)
  List<String> w = S.warnings();
  String key = String.join("|", w);
  if (!key.equals(warnedSettings)) {
    warnedSettings = key;
    for (String line : w) plugin.getLogger().warning("[NxPerf] WARN plugin=" + plugin.getName() + " " + line + " (applied as set)");
  }
}

private static void tick() {
  long now = System.nanoTime();
  if (secondStart == 0) secondStart = now;
  if (!paused && S.autoDisable && ownNanosTick / 1e6 > S.freezeMs) pause("freeze", "one tick of this plugin's listeners took " + NxPerfCore.fmt(ownNanosTick / 1e6) + " ms (perf.freeze-ms=" + NxPerfCore.fmt(S.freezeMs) + ")");

