1	/**
2	 * Valheim — BepInEx plugins from Thunderstore.
3	 *
4	 * Server: lloesche/valheim-server (prisma/catalog.ts), `-v /opt/valheim/config:/config`.
5	 * With the BepInEx server type (`BEPINEX=true`, worker/game-config.ts) the image
6	 * itself copies /config/bepinex/plugins into its BepInEx install on every
7	 * start — that folder is the documented drop point, and the only one this
8	 * installer writes to. BepInEx loads plugin DLLs recursively, so each package
9	 * gets its own `<Namespace>-<Name>` folder (the r2modman/Thunderstore
10	 * convention), which is also what makes uninstall exact.
11	 *
12	 * Package layout (Thunderstore's documented structure): manifest.json,
13	 * icon.png, README.md at the root, and the payload either at the root, under
14	 * `plugins/`, or under `BepInEx/plugins/`. Everything that isn't plugin
15	 * payload is handled explicitly:
16	 *   - `config/` defaults are skipped (BepInEx writes a config on first run);
17	 *   - `patchers/`, `core/`, `monomod/` need BepInEx's preloader folders, which
18	 *     this server type doesn't sync from /config — such packages are refused
19	 *     with that reason rather than installed half-working;
20	 *   - BepInExPack (the loader itself) is never installed: the server image
21	 *     provides BepInEx.
22	 *
23	 * Dependencies come from the package's own declared list (exact versions, as
24	 * the author pinned them). Thunderstore publishes no file checksum in its API,
25	 * so downloads are size-capped, zip-validated and recorded with our own sha256.
26	 */
27	import { readZip, ArchiveError } from "../archive";
28	import { fetchJson } from "../safe-fetch";
29	import { joinUnder, isSafeSegment } from "../paths";
30	import type { CatalogFacts, Compat, FamilyInstaller, InstallerCtx, PlacedFile, ResolvedPackage, ServerFacts } from "../types";
31	
32	const TS = "https://thunderstore.io/api/experimental/package";
33	const VALHEIM_PLUGINS = "/opt/valheim/config/bepinex/plugins";
34	/** Host side of the container's /opt/valheim/bepinex/BepInEx/plugins (`-v /opt/valheim/data:/opt/valheim`). */
35	export const VALHEIM_SYNCED_PLUGINS = "/opt/valheim/data/bepinex/BepInEx/plugins";
36	
37	/**
38	 * The copy lloesche's bootstrap made of a file we placed under VALHEIM_PLUGINS.
39	 * Its sync_bepinex_loadables() is `rsync -a` WITHOUT --delete; only image
40	 * builds from 2026-09-19 (upstream #811) prune files that left /config, via a
41	 * manifest. On any older image a file we moved aside or removed would keep
42	 * loading from this copy — so the engine removes it (sha-checked) itself.
43	 */
44	export function valheimSyncedCopy(p: string): string | null {
45	  return p.startsWith(VALHEIM_PLUGINS + "/") ? VALHEIM_SYNCED_PLUGINS + p.slice(VALHEIM_PLUGINS.length) : null;
46	}
47	
48	type TsVersion = { namespace: string; name: string; version_number: string; full_name: string; download_url: string; dependencies: string[]; file_size?: number; is_active?: boolean };
49	type TsPackage = { namespace: string; name: string; full_name: string; is_deprecated?: boolean; latest: TsVersion };
50	
51	/** "Author-Name-1.2.3" → parts. Names may contain dashes? Thunderstore forbids them in name/namespace. */
52	export function parseDepString(s: string): { namespace: string; name: string; version: string } | null {
53	  const m = /^([A-Za-z0-9_]+)-([A-Za-z0-9_]+)-(\d+\.\d+\.\d+)$/.exec(s.trim());
54	  return m ? { namespace: m[1], name: m[2], version: m[3] } : null;
55	}
56	
57	export function isLoaderPack(namespace: string, name: string): boolean {
58	  return /bepinexpack/i.test(name) || (namespace === "denikson" && /bepinex/i.test(name));
59	}
60	
61	/**
62	 * Map a Thunderstore package's files to BepInEx plugin files under
63	 * `<pluginsDir>/<folder>/`. Pure; exported for the fixture tests.
64	 */
65	export function bepinexPlacement(entries: { path: string[]; dir: boolean; data: Buffer }[], pluginsDir: string, folder: string): PlacedFile[] | { error: string } {
66	  if (!isSafeSegment(folder)) return { error: "unsafe package folder name" };
67	  const META = new Set(["manifest.json", "icon.png", "readme.md", "changelog.md", "license", "license.md", "license.txt"]);
68	  const out: PlacedFile[] = [];
69	  for (const e of entries) {
70	    if (e.dir) continue;
71	    let segs = e.path;
72	    const lower = segs.map((s) => s.toLowerCase());
73	    if (segs.length === 1 && META.has(lower[0])) continue;
74	    if (lower[0] === "bepinex") { segs = segs.slice(1); lower.shift(); }
75	    const top = lower[0];
76	    if (["patchers", "core", "monomod"].includes(top)) {
77	      return { error: `this package needs BepInEx ${top}/ files, which this server type can't load from the plugins folder` };
78	    }
79	    if (top === "config") continue; // defaults: BepInEx generates the real config on first run
80	    if (top === "plugins") segs = segs.slice(1);
81	    if (segs.length === 0) continue;
82	    out.push({ path: joinUnder(pluginsDir, [folder, ...segs]), data: e.data });
83	  }
84	  return out;
85	}
86	
87	export const valheimInstaller: FamilyInstaller = {
88	  family: "valheim",
89	  sources: ["thunderstore"],
90	  mechanism: "BepInEx plugins from Thunderstore into /opt/valheim/config/bepinex/plugins/<Author-Name>/ (the image syncs them into BepInEx on start).",
91	  restartRequired: true,
92	  syncedRoot: VALHEIM_SYNCED_PLUGINS,
93	  syncedCopy: valheimSyncedCopy,
94	
95	  compat(_mod: CatalogFacts, server: ServerFacts): Compat {
96	    if ((server.variant ?? "vanilla") !== "bepinex") {
97	      return { verdict: "mismatch", detail: "Mods need the BepInEx server type — switch it in Settings (your world is kept)." };
98	    }
99	    return { verdict: "unknown", reason: "no-list", detail: "Thunderstore doesn't publish a game-version list; mods load against the current Valheim build." };
100	  },
101	
102	  async detect(fs, server) {
103	    if ((server.variant ?? "vanilla") !== "bepinex") return { error: "Mods need the BepInEx server type. Switch to it in Settings (your world is kept), then install." };
104	    if ((await fs.stat("/opt/valheim/config"))?.type !== "dir") return { error: "Couldn't find this server's Valheim config folder — is the server fully set up?" };
105	    await fs.mkdirp(VALHEIM_PLUGINS);
106	    return { base: "/opt/valheim/config", dirs: { plugins: VALHEIM_PLUGINS }, gameVersion: null };
107	  },
108	
109	  async resolve(mod, ctx: InstallerCtx) {
110	    const id = (mod.sourceId ?? "").trim();
111	    const [ns, ...rest] = id.split("-");
112	    if (!ns || rest.length !== 1) return { error: "This Thunderstore entry has no valid Author-Name id." };
113	    const notes: string[] = [];
114	    const order: ResolvedPackage[] = [];
115	    const seen = new Set<string>();
116	    const visit = async (namespace: string, name: string, version: string | null, isRoot: boolean, depth: number): Promise<string | null> => {
117	      const k = `${namespace}-${name}`.toLowerCase();
118	      if (seen.has(k)) return null;
119	      seen.add(k);
120	      if (isLoaderPack(namespace, name)) {
121	        notes.push("BepInEx itself is provided by your server — not installed separately.");
122	        return null;
123	      }
124	      if (seen.size > 40) return "This mod pulls in more than 40 dependencies — too many for one click.";
125	      let v: TsVersion;
126	      try {
127	        if (version) v = await fetchJson<TsVersion>(ctx.fetcher, `${TS}/${encodeURIComponent(namespace)}/${encodeURIComponent(name)}/${encodeURIComponent(version)}/`);
128	        else {
129	          const p = await fetchJson<TsPackage>(ctx.fetcher, `${TS}/${encodeURIComponent(namespace)}/${encodeURIComponent(name)}/`);
130	          if (p.is_deprecated && isRoot) notes.push(`${p.full_name} is marked deprecated by its author.`);
131	          v = p.latest;
132	        }
133	      } catch {
134	        return isRoot ? `Couldn't find ${mod.name} on Thunderstore (it may have been removed).` : `${mod.name} needs ${namespace}-${name}${version ? ` ${version}` : ""}, which couldn't be found on Thunderstore.`;
135	      }
136	      const requires: string[] = [];
137	      if (depth < 6) {
138	        for (const d of v.dependencies ?? []) {
139	          const dep = parseDepString(d);
140	          if (!dep) return `${v.full_name} declares a dependency we can't parse (${d}).`;
141	          const e = await visit(dep.namespace, dep.name, dep.version, false, depth + 1);
142	          if (e) return e;
143	          if (!isLoaderPack(dep.namespace, dep.name)) requires.push(`thunderstore:${dep.namespace}-${dep.name}`);
144	        }
145	      }
146	      order.push({
147	        key: `thunderstore:${v.namespace}-${v.name}`,
148	        name: isRoot ? mod.name : `${v.namespace}-${v.name}`,
149	        version: v.version_number,
150	        versionId: v.full_name,
151	        file: { url: v.download_url, filename: `${v.full_name}.zip`, size: v.file_size ?? null, hashes: {}, mirrorKey: { source: "thunderstore", projectId: `${v.namespace}-${v.name}`, versionId: v.version_number } },
152	        placement: "bepinex",
153	        requires,
154	        incompatible: [],
155	        root: isRoot,
156	      });
157	      return null;
158	    };
159	    const err = await visit(ns, rest[0], null, true, 0);
160	    if (err) return { error: err };
161	    if (!order.length) return { error: `${mod.name} is the mod loader itself — your server already provides BepInEx.` };
162	    notes.push("Thunderstore doesn't publish checksums; downloads are size-capped and archive-checked.");
163	    return { packages: order, notes };
164	  },
165	
