    }
    return { verdict: "unknown", reason: "no-list", detail: "Thunderstore doesn't publish a game-version list; mods load against the current Valheim build." };
  },

  async detect(fs, server) {
    if ((server.variant ?? "vanilla") !== "bepinex") return { error: "Mods need the BepInEx server type. Switch to it in Settings (your world is kept), then install." };
    if ((await fs.stat("/opt/valheim/config"))?.type !== "dir") return { error: "Couldn't find this server's Valheim config folder — is the server fully set up?" };
    await fs.mkdirp(VALHEIM_PLUGINS);
    return { base: "/opt/valheim/config", dirs: { plugins: VALHEIM_PLUGINS }, gameVersion: null };
  },

