// One-off, owner-signed-off staff reply (ticket cmv774yvj0itxhla9kx5jvugr, 2026-10-14). Uses the platform's shared
// write path (lib/reply-core.ts: message + status ANSWERED + notification/email) and the Discord mirror like the
// dashboard reply box does.
import { writeTicketReply } from "/tank/dev-worktrees/cyrus-rc7/lib/reply-core";
import { mirrorTicketReplyToDiscord } from "/tank/dev-worktrees/cyrus-rc7/lib/discord-bridge";

const BODY = `Hi Alejandro,

Thanks for the screenshot, it showed exactly what was going on. FiresSteamworksPatcher ships part of itself as a BepInEx "patcher", and our installer wasn't set up to place that kind of file, so it stopped with that error. That was on our side, not your server or anything you did.

We've fixed the installer and installed FiresSteamworksPatcher on your TERRAHEIM server for you. Please restart the server when convenient so it loads.

One thing to know: this patcher is built to run alongside FiresGhettoNetworking (which you already have installed), so it should work together with it.

If anything errors or the server doesn't start cleanly after the restart, reply here and we'll look straight away.

Thanks for your patience,
Nxeon`;

(async () => {
  const r = await writeTicketReply({
    actorId: "cmrxclbq20007hln6ryf7j2hg",
    actorIsSupportStaff: true,
    ticketId: "cmv774yvj0itxhla9kx5jvugr",
    body: BODY,
  });
  console.log(JSON.stringify({ error: r.error ?? null, isStaff: r.isStaff ?? null }));
  if (!r.error) await mirrorTicketReplyToDiscord("cmv774yvj0itxhla9kx5jvugr", BODY, Boolean(r.isStaff)).catch((e) => console.log("discord mirror skipped:", String(e).slice(0, 120)));
  process.exit(r.error ? 1 : 0);
})();

