describe("launch-check drift guards", () => {
  it("placeholder-keys.json is exactly the catalog's PLACEHOLDER-marked settings", () => {
    const want = CYRUS_SETTINGS.filter((s) => /PLACEHOLDER/.test(s.description)).map((s) => s.key).sort();
    const have = JSON.parse(readFileSync(path.join(ROOT, "scripts/cyrus/lib/placeholder-keys.json"), "utf8"));
    assert.deepEqual(have, want);
  });
  it("every first segment the Cyrus host routes to the app is in REQUIRED_APP_PREFIXES, and each prefix routes", async () => {
    const m = await mod();
    const cfg = bridgeConfig({ CYRUS_DOMAIN_MODE: "1", CYRUS_HOSTS: "cyrus.my", APP_URL: "https://nxeon.cloud" });
    for (const p of Object.keys(CYRUS_APP_PATHS)) assert.ok(m.REQUIRED_APP_PREFIXES.includes(p.slice(1)), `${p} missing`);
    for (const pre of m.REQUIRED_APP_PREFIXES) {
      const tries = [`/${pre}`, `/${pre}/x`, `/${pre}/handoff`];
      const r = { kind: tries.some((t) => cyrusHostRoute({ pathname: t, search: "", method: "GET", cfg }).kind !== "notfound") ? "ok" : "notfound" };
      assert.notEqual(r.kind, "notfound", `/${pre} would 404 on the Cyrus host`);
    }
  });
});
